using System.Security;
using System.Security.Cryptography;
using Wasmtime;

// The narrow admission gate used by the synthetic, trusted NativeAOT probe.
// IMPORTANT: this is NOT a production untrusted guest loader. The approved
// digest is generated by the trusted test fixture, not supplied by a tenant.
// Production code must authenticate a build-time manifest, forbid runtime
// Wasm compilation under the strict-AOT policy, and independently review any
// precompiled Wasmtime native-code artifact before deserialization.
internal static class TrustedProbeModuleAdmission
{
    private const int MaxFixtureBytes = 1024 * 1024;

    internal static Module Load(
        Engine engine,
        ReadOnlySpan<byte> wasm,
        ReadOnlySpan<byte> approvedSha256,
        string name = "trusted-synthetic-fixture")
    {
        ArgumentNullException.ThrowIfNull(engine);
        if (approvedSha256.Length != SHA256.HashSizeInBytes)
            throw new SecurityException("invalid approved module digest length");
        if (wasm.Length < 8 || wasm.Length > MaxFixtureBytes)
            throw new SecurityException("Wasm module exceeds bounded fixture admission");
        if (wasm[0] != 0 || wasm[1] != (byte)'a' ||
            wasm[2] != (byte)'s' || wasm[3] != (byte)'m' ||
            wasm[4] != 1 || wasm[5] != 0 || wasm[6] != 0 || wasm[7] != 0)
            throw new SecurityException("invalid Wasm binary header/version");
        var actualSha256 = SHA256.HashData(wasm);
        if (!CryptographicOperations.FixedTimeEquals(actualSha256, approvedSha256))
            throw new SecurityException("Wasm digest does not match the trusted fixture");

        // This compiles Wasm at runtime: intentionally permitted ONLY in the
        // developer probe and MUST NOT be routed into released untrusted mode.
        // A SHA-256 digest by itself does not authenticate tenant input.
        var module = Module.FromBytes(engine, name, wasm);
        if (module.Imports.Count == 0) return module;
        module.Dispose();
        throw new SecurityException("Wasm guest imports denied");
    }
}
